// PRODUCCIÓN: filtra MENSAJE vacío + TELEFONO 9-15 dígitos.
// Límite duro: 6 leads por ejecución (cron horario, 6 msgs/run = 78 max/día en horario 9-21 ES).
// Si nadie pasa, devuelve UN item placeholder con _no_leads=true para que la rama "vacío" se ejecute.
const MAX_PER_RUN = 6;
const allItems = $input.all();
const out = [];
for (const it of allItems) {
  const j = it.json;
  const mensaje = String(j.MENSAJE ?? '').trim().toUpperCase();
  const tel = String(j.TELEFONO ?? '').replace(/[^0-9]/g, '');
  const mensajeVacio = (mensaje === '' || mensaje === 'NULL' || mensaje === 'UNDEFINED');
  const telValido = /^[0-9]{9,15}$/.test(tel);
  if (mensajeVacio && telValido) out.push({ json: { ...j, TELEFONO: tel, _no_leads: false } });
  if (out.length >= MAX_PER_RUN) break;
}
if (out.length === 0) {
  return [{ json: { _no_leads: true, _total_filas_leidas: allItems.length } }];
}
return out;

const item = $input.item.json;
const raw = String(item.TELEFONO || '').replace(/[^0-9]/g, '');
// Normalizar a formato internacional sin '+'
const numero_internacional = (raw.length === 9 && /^[67]/.test(raw)) ? ('34' + raw) : raw;

const TITULO = item.TITULO || 'la oferta publicada';
const CIUDAD = item.CIUDAD || 'vuestra zona';

// Dos plantillas oficiales — elegir aleatoriamente A o B
const A = `Hola soy Diego,\n\nHe visto vuestra oferta de ${TITULO} en ${CIUDAD} y os escribo porque estamos ayudando a empresas a encontrar perfiles cualificados mucho más rápido.\n\nAhora mismo está siendo complicado cubrir este tipo de puestos.\n\n¿Os interesa que os explique cómo lo haríamos en vuestro caso?`;

const B = `Hola soy Diego,\n\nHe visto vuestra oferta de ${TITULO} en ${CIUDAD}.\n\nJusto estamos trabajando con varias empresas del sector enviándoles candidatos listos para entrevista en pocos días.\n\n¿Queréis que os cuente cómo lo estamos haciendo?`;

const mensaje = Math.random() < 0.5 ? A : B;
return { json: { ...item, mensaje_generado: mensaje, numero_internacional } };

const evoResp = $input.item.json;
const sent = !evoResp.error && evoResp.key;
const src = $('Generar mensaje').item.json;
const err = evoResp.error || evoResp.message || '';
return {
  json: {
    TELEFONO: src.TELEFONO,
    MENSAJE: sent ? 'ENVIADO' : '',
    ERROR: sent ? '' : String(err).slice(0, 300)
  }
};

// Resumen del día. Detecta marker _no_leads.
const items = $input.all().map(it => it.json);
const isEmpty = items.length === 1 && items[0]._no_leads === true;
const fecha = new Date().toLocaleString('es-ES', { timeZone: 'Europe/Madrid', dateStyle: 'short', timeStyle: 'short' });

let texto;
if (isEmpty) {
  texto = `📊 *Resumen AgenciaHyC* — ${fecha}\n\nℹ️ Hoy no había leads pendientes.\nTodas las filas con MENSAJE != vacío fueron ignoradas.`;
} else {
  const total = items.length;
  const enviados = items.filter(i => String(i.MENSAJE).toUpperCase() === 'ENVIADO').length;
  const errores = items.filter(i => i.ERROR && String(i.ERROR).trim() !== '');
  texto = `📊 *Resumen AgenciaHyC* — ${fecha}\n\n` +
    `✅ Enviados OK: ${enviados}\n` +
    `❌ Con error: ${errores.length}\n` +
    `📋 Total procesados: ${total}`;
  if (errores.length > 0) {
    const errLines = errores.slice(0, 10).map(e => `• ${e.TELEFONO}: ${String(e.ERROR).slice(0, 80)}`).join('\n');
    texto += `\n\n*Errores (primeros 10):*\n${errLines}`;
    if (errores.length > 10) texto += `\n…y ${errores.length - 10} más`;
  }
}
return [{ json: { resumen_texto: texto, numero_destino: '573012661158' } }];

const total = $input.item.json._total_filas_leidas ?? 0;
const fecha = new Date().toLocaleString('es-ES', { timeZone: 'Europe/Madrid', dateStyle: 'short', timeStyle: 'short' });
const texto = `📊 *Resumen AgenciaHyC* — ${fecha}

ℹ️ Hoy no había leads pendientes con MENSAJE vacío.

📋 Filas revisadas en la hoja: ${total}`;
return { json: { resumen_texto: texto, numero_destino: '573012661158' } };
